"""Natural offline handoff and legacy CLI compatibility, using generated bytes/fakes.

The real recorder closes one synthetic FLV container and persists its metadata.
No payload is decoded and no model, FFmpeg, network or child process is used.
"""
import builtins
import json
import os
from pathlib import Path
import sys
from types import ModuleType, SimpleNamespace

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT / "scripts"), str(ROOT)]
import stream_recorder as recorder


def forbidden(*_args, **_kwargs):
    pytest.fail("customer offline handoff must not enter the legacy transcriber chain")


def flv_tag(kind, payload, timestamp=0):
    return (bytes([kind]) + len(payload).to_bytes(3, "big")
            + timestamp.to_bytes(3, "big") + b"\0\0\0\0" + payload
            + (11 + len(payload)).to_bytes(4, "big"))


def test_customer_natural_offline_closes_source_without_legacy_spawn(tmp_path, monkeypatch):
    data, project = tmp_path / "synthetic customer data", tmp_path / "synthetic project"
    data.mkdir()
    (project / "scripts").mkdir(parents=True)
    old_script = project / "scripts/transcribe_backfill.py"
    old_script.write_text("# synthetic; never executed\n", encoding="utf-8")
    old_lock, old_log = data / ".tr_synthetic_2000-01-01.lock", data / "transcribe_synthetic.log"
    old_lock.write_bytes(b"12345")
    old_log.write_bytes(b"retained legacy log\n")
    original = {path: path.read_bytes() for path in (old_script, old_lock, old_log)}
    customer = {"data": str(data), "root": str(project), "python": "never-used-python"}
    monkeypatch.setattr(recorder, "CUSTOMER", customer)
    monkeypatch.setattr(recorder, "DATA", data)
    monkeypatch.setattr(recorder, "ROOT", project)
    monkeypatch.setattr(recorder, "_CUSTOMER_IDENTITY", None)
    monkeypatch.setattr(recorder, "_TRANSCRIBE_CHILDREN", [])
    monkeypatch.setattr(recorder.main, "_idle_logged", False, raising=False)
    monkeypatch.setattr(recorder.sys, "argv", ["synthetic-recorder", "--tag", "synthetic"])
    monkeypatch.setitem(sys.modules, "curl_cffi", ModuleType("curl_cffi"))
    monkeypatch.setattr(recorder.signal, "signal", lambda *_args: None)
    monkeypatch.setattr(recorder, "resolve_node", lambda: "synthetic-unused-node")
    monkeypatch.setattr(recorder, "_process_created_at", lambda *_args: 1234.0)
    monkeypatch.setattr(recorder, "publish_role_ready", lambda *_args: {"state": "alive", "pid": 123, "created": 1234.0})
    messages, events, clock, stop = [], [], [1800000000.0], [False]
    monkeypatch.setattr(recorder, "Log", lambda *_args: messages.append)
    monkeypatch.setattr(recorder, "now", lambda: clock[0])
    monkeypatch.setattr(recorder, "customer_stop_requested", lambda *_args: stop[0])
    monkeypatch.setattr(recorder, "stop_requested", lambda *_args: False)
    monkeypatch.setattr(recorder, "read_watch_state", lambda *_args: {
        "is_live": True, "live_status": 1, "web_rid": "synthetic-room", "room_id_str": "synthetic-session"})
    monkeypatch.setattr(recorder, "capture_stream", lambda *_args: {"synthetic": True})
    monkeypatch.setattr(recorder.subprocess, "Popen", forbidden)
    monkeypatch.setattr(recorder, "pid_owns_file", forbidden)
    def open_file(path, *args, **kwargs):
        name = Path(path).name
        if name.startswith((".tr_", "transcribe_")):
            forbidden()
        return builtins.open(path, *args, **kwargs)

    monkeypatch.setattr(recorder, "open", open_file, raising=False)
    real_exists = Path.exists

    def exists(path):
        if path.name.startswith(".tr_") or path.name == "transcribe_backfill.py":
            forbidden()
        return real_exists(path)

    monkeypatch.setattr(Path, "exists", exists)
    # Valid FLV container structure; its AAC payload is generated and never decoded.
    blob = (recorder.FLV_HEADER + flv_tag(8, b"\xaf\0\x12\x10")
            + flv_tag(8, b"\xaf\x01" + b"S" * 4200, 21))

    def pull(_tag, _rid, writer, *_args):
        events.append("pull_offline")
        writer.begin_connection()
        writer.feed(blob)
        return "offline"

    monkeypatch.setattr(recorder, "pull_loop", pull)
    actual_handoff = recorder.spawn_transcribe
    closed_paths = []

    def handoff(tag, day, log):
        folder = data / ("audio_%s_%s" % (tag, day))
        meta = json.loads((folder / "meta.json").read_text(encoding="utf-8"))
        assert meta["stop_reason"] == "offline" and len(meta["segments"]) == 1
        source = folder / meta["segments"][0]["file"]
        closed = recorder.audio_segments.verify_closed(data, folder, source.name)
        assert closed["size"] == len(blob) and source.read_bytes() == blob
        events.append("closed_meta_before_handoff")
        closed_paths.append(source)
        actual_handoff(tag, day, log)
        events.append("managed_handoff_returned")

    monkeypatch.setattr(recorder, "spawn_transcribe", handoff)

    def wait(seconds, should_stop):
        assert seconds == 10 and events[-1] == "managed_handoff_returned"
        events.append("wait_after_handoff")
        clock[0] += seconds
        stop[0] = True
        assert should_stop()
        return True

    monkeypatch.setattr(recorder, "interruptible_wait", wait)
    assert recorder._record_main() == 0
    assert events == ["pull_offline", "closed_meta_before_handoff", "managed_handoff_returned", "wait_after_handoff"]
    assert len(closed_paths) == 1 and closed_paths[0].read_bytes() == blob
    assert all(path.read_bytes() == value for path, value in original.items())
    assert recorder._TRANSCRIBE_CHILDREN == []
    assert any("应用受管转写补扫" in message for message in messages)
    assert not (data / "stream_synthetic.pid").exists()
    assert not list(data.rglob("*.tmp"))


def test_legacy_handoff_keeps_cli_environment_lock_and_closed_log(tmp_path, monkeypatch):
    data, project = tmp_path / "synthetic legacy data", tmp_path / "synthetic project"
    data.mkdir()
    (project / "scripts").mkdir(parents=True)
    script = project / "scripts/transcribe_backfill.py"
    script.write_bytes(b"# synthetic legacy entry; never executed\n")
    before_script = script.read_bytes()
    monkeypatch.setattr(recorder, "CUSTOMER", None)
    monkeypatch.setattr(recorder, "DATA", data)
    monkeypatch.setattr(recorder, "ROOT", project)
    children = [SimpleNamespace(poll=forbidden)]
    monkeypatch.setattr(recorder, "_TRANSCRIBE_CHILDREN", children)
    monkeypatch.setenv("PYTHONIOENCODING", "synthetic-parent-encoding")
    monkeypatch.setenv("PYTHONUTF8", "0")
    monkeypatch.setenv("DY_CUSTOMER_CONTEXT", "synthetic-unused-context")
    monkeypatch.setenv("DY_CUSTOMER_STOP", "synthetic-unused-stop")
    monkeypatch.setenv("DY_CUSTOMER_ROLE_NONCE", "synthetic-unused-nonce")
    monkeypatch.setenv("HANDOFF_TEST_SENTINEL", "synthetic-inherited-value")
    tag, day = "synthetic", "2000-01-01"
    lock = data / (".tr_%s_%s.lock" % (tag, day))
    lock.write_text("123", encoding="utf-8")
    ownership, spawned, messages = [], [], []

    def owns(pid, path, **kwargs):
        ownership.append((pid, path, kwargs))
        return False

    monkeypatch.setattr(recorder, "pid_owns_file", owns)

    def popen(command, **options):
        assert not options["stdout"].closed
        options["stdout"].write("synthetic child log\n")
        spawned.append((command, options))
        return SimpleNamespace(pid=456)

    monkeypatch.setattr(recorder.subprocess, "Popen", popen)
    recorder.spawn_transcribe(tag, day, messages.append)
    assert ownership == [(123, lock, {"require_identity": True})]
    assert len(spawned) == 1
    command, options = spawned[0]
    assert command == [sys.executable, str(script), "--tag", tag, "--date", day]
    assert options["cwd"] == str(project)
    assert options["stderr"] == recorder.subprocess.STDOUT
    assert options["stdin"] == recorder.subprocess.DEVNULL
    assert options["creationflags"] == recorder.NO_WINDOW
    env = options["env"]
    assert env["PYTHONIOENCODING"] == "utf-8" and env["PYTHONUTF8"] == "1"
    for key in ("DY_CUSTOMER_CONTEXT", "DY_CUSTOMER_STOP", "DY_CUSTOMER_ROLE_NONCE", "HANDOFF_TEST_SENTINEL"):
        assert env[key] == os.environ[key]
    assert os.environ["PYTHONIOENCODING"] == "synthetic-parent-encoding" and os.environ["PYTHONUTF8"] == "0"
    assert options["stdout"].closed
    assert (data / "transcribe_synthetic.log").read_text(encoding="utf-8") == "synthetic child log\n"
    assert lock.read_text(encoding="utf-8") == "456"
    assert recorder._TRANSCRIBE_CHILDREN is children and len(children) == 1
    assert script.read_bytes() == before_script
    assert any("pid=456" in message for message in messages)
    assert not list(data.rglob("*.tmp"))
